ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  "ActivityInput": {
    "message": "Faltan los siguientes parámetros: " ++ vars.missingParameters,
    "messageCode": "PROCORDER02"
  }
}

%dw 2.0
output application/xml writeDeclaration=false, encoding="UTF-8"
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns tem http://tempuri.org/
ns orq http://www.etb.com.co/orquestador
ns orq1 http://schemas.datacontract.org/2004/07/Orquestador.Contracts.Entidades.Agendamiento
---
soapenv#Envelope @("xmlns:tem": "http://tempuri.org/",
                    "xmlns:orq": "http://www.etb.com.co/orquestador",
                    "xmlns:orq1": "http://schemas.datacontract.org/2004/07/Orquestador.Contracts.Entidades.Agendamiento")
                    :{
    soapenv#Header: null,
    soapenv#Body: {
        tem#CompletarOrden: {
            tem#solicitud:{
                orq#Encabezado: {
                    orq#Sistema: {
                        orq#IdCorrelacion: payload.ProcessOPInput.WSRequestHeader2.System.correlationID,
                        orq#Nombre: payload.ProcessOPInput.WSRequestHeader2.System.name
                    }
                },
                orq#DatosSolicitud: {
                    orq#Orden: payload.ProcessOPInput.ProcessRequest.Order,
                    orq#Comentarios: payload.ProcessOPInput.ProcessRequest.Comments
                }
            }
        }
    }
}

